-- MySQL 8.0.16+ enforces CHECK constraints. UTC timestamps throughout.
CREATE TABLE products (id BIGINT AUTO_INCREMENT PRIMARY KEY, sku VARCHAR(64) NOT NULL UNIQUE, name VARCHAR(255) NOT NULL, category VARCHAR(120) NOT NULL, unit VARCHAR(32) NOT NULL, price DECIMAL(19,2) NOT NULL, active BIT NOT NULL DEFAULT 1, CHECK(price>=0), INDEX idx_products_category_id(category,id));
CREATE TABLE customers (id BIGINT AUTO_INCREMENT PRIMARY KEY, code VARCHAR(64) NOT NULL UNIQUE, name VARCHAR(255) NOT NULL, phone VARCHAR(32), email VARCHAR(255), INDEX idx_customers_phone(phone));
CREATE TABLE employees (id BIGINT AUTO_INCREMENT PRIMARY KEY, code VARCHAR(64) NOT NULL UNIQUE, name VARCHAR(255) NOT NULL, email VARCHAR(255), department VARCHAR(120), active BIT NOT NULL DEFAULT 1);
CREATE TABLE warehouses (id BIGINT AUTO_INCREMENT PRIMARY KEY, code VARCHAR(64) NOT NULL UNIQUE, name VARCHAR(255) NOT NULL);
CREATE TABLE roles (id BIGINT AUTO_INCREMENT PRIMARY KEY, code VARCHAR(64) NOT NULL UNIQUE, name VARCHAR(255) NOT NULL);
CREATE TABLE permissions (id BIGINT AUTO_INCREMENT PRIMARY KEY, code VARCHAR(64) NOT NULL UNIQUE, name VARCHAR(255) NOT NULL);
CREATE TABLE user_accounts (id BIGINT AUTO_INCREMENT PRIMARY KEY, username VARCHAR(100) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, employee_id BIGINT, enabled BIT NOT NULL DEFAULT 1, FOREIGN KEY(employee_id) REFERENCES employees(id));
CREATE TABLE user_roles (user_id BIGINT NOT NULL, role_id BIGINT NOT NULL, PRIMARY KEY(user_id,role_id), FOREIGN KEY(user_id) REFERENCES user_accounts(id), FOREIGN KEY(role_id) REFERENCES roles(id));
CREATE TABLE role_permissions (role_id BIGINT NOT NULL, permission_id BIGINT NOT NULL, PRIMARY KEY(role_id,permission_id), FOREIGN KEY(role_id) REFERENCES roles(id), FOREIGN KEY(permission_id) REFERENCES permissions(id));
CREATE TABLE inventory_balances (id BIGINT AUTO_INCREMENT PRIMARY KEY, warehouse_id BIGINT NOT NULL, product_id BIGINT NOT NULL, quantity BIGINT NOT NULL DEFAULT 0, UNIQUE KEY uq_balance(warehouse_id,product_id), FOREIGN KEY(warehouse_id) REFERENCES warehouses(id), FOREIGN KEY(product_id) REFERENCES products(id), CHECK(quantity>=0));
CREATE TABLE stock_receipts (id BIGINT AUTO_INCREMENT PRIMARY KEY, reference VARCHAR(64) NOT NULL UNIQUE, warehouse_id BIGINT NOT NULL, supplier VARCHAR(255), status VARCHAR(32) NOT NULL, approval_level INT NOT NULL DEFAULT 0, created_by BIGINT NOT NULL, first_approver_id BIGINT, created_at DATETIME(6) NOT NULL, FOREIGN KEY(warehouse_id) REFERENCES warehouses(id), FOREIGN KEY(created_by) REFERENCES user_accounts(id), FOREIGN KEY(first_approver_id) REFERENCES user_accounts(id), CHECK(status IN ('PENDING','APPROVED','REJECTED')), CHECK(approval_level BETWEEN 0 AND 2), INDEX idx_receipt_status_id(status,id));
CREATE TABLE receipt_lines (id BIGINT AUTO_INCREMENT PRIMARY KEY, receipt_id BIGINT NOT NULL, product_id BIGINT NOT NULL, quantity BIGINT NOT NULL, unit_cost DECIMAL(19,2) NOT NULL, UNIQUE KEY uq_receipt_product(receipt_id,product_id), FOREIGN KEY(receipt_id) REFERENCES stock_receipts(id), FOREIGN KEY(product_id) REFERENCES products(id), CHECK(quantity>0), CHECK(unit_cost>=0));
CREATE TABLE approvals (id BIGINT AUTO_INCREMENT PRIMARY KEY, receipt_id BIGINT NOT NULL, actor_id BIGINT NOT NULL, approval_level INT NOT NULL, decision VARCHAR(32) NOT NULL, note VARCHAR(1000), created_at DATETIME(6) NOT NULL, UNIQUE KEY uq_receipt_level(receipt_id,approval_level), FOREIGN KEY(receipt_id) REFERENCES stock_receipts(id), FOREIGN KEY(actor_id) REFERENCES user_accounts(id), CHECK(decision IN ('APPROVE','REJECT')), CHECK(approval_level IN (1,2)));
CREATE TABLE sales_orders (id BIGINT AUTO_INCREMENT PRIMARY KEY, reference VARCHAR(64) NOT NULL UNIQUE, customer_id BIGINT NOT NULL, warehouse_id BIGINT NOT NULL, status VARCHAR(32) NOT NULL, total DECIMAL(19,2) NOT NULL, created_by BIGINT NOT NULL, created_at DATETIME(6) NOT NULL, FOREIGN KEY(customer_id) REFERENCES customers(id), FOREIGN KEY(warehouse_id) REFERENCES warehouses(id), FOREIGN KEY(created_by) REFERENCES user_accounts(id), CHECK(status IN ('PLACED','FULFILLED')), CHECK(total>=0), INDEX idx_order_customer_id(customer_id,id), INDEX idx_order_status_created(status,created_at));
CREATE TABLE order_lines (id BIGINT AUTO_INCREMENT PRIMARY KEY, order_id BIGINT NOT NULL, product_id BIGINT NOT NULL, quantity BIGINT NOT NULL, unit_price DECIMAL(19,2) NOT NULL, UNIQUE KEY uq_order_product(order_id,product_id), FOREIGN KEY(order_id) REFERENCES sales_orders(id), FOREIGN KEY(product_id) REFERENCES products(id), CHECK(quantity>0), CHECK(unit_price>=0));
CREATE TABLE stock_movements (id BIGINT AUTO_INCREMENT PRIMARY KEY, warehouse_id BIGINT NOT NULL, product_id BIGINT NOT NULL, quantity BIGINT NOT NULL, kind VARCHAR(32) NOT NULL, document_id BIGINT NOT NULL, created_at DATETIME(6) NOT NULL, FOREIGN KEY(warehouse_id) REFERENCES warehouses(id), FOREIGN KEY(product_id) REFERENCES products(id), UNIQUE KEY uq_movement(kind,document_id,product_id), INDEX idx_movement_history(warehouse_id,product_id,id), CHECK(kind IN ('RECEIPT','SALE','OPENING')));
CREATE TABLE audit_logs (id BIGINT AUTO_INCREMENT PRIMARY KEY, actor_id BIGINT NOT NULL, action VARCHAR(64) NOT NULL, entity_type VARCHAR(64) NOT NULL, entity_id BIGINT NOT NULL, details VARCHAR(2000), created_at DATETIME(6) NOT NULL, FOREIGN KEY(actor_id) REFERENCES user_accounts(id), INDEX idx_audit_entity(entity_type,entity_id,id), INDEX idx_audit_actor(actor_id,id));
